{
  "primary_meaning": "the eternal dwelling place of God and the final abode of the redeemed in perfect communion with Him",
  "primary_basis": [
    "John 14:2-3",
    "Revelation 21:1-4",
    "Matthew 6:9",
    "Philippians 3:20",
    "2 Corinthians 5:1",
    "Hebrews 11:16"
  ],
  "alternatives": [
    {
      "meaning": "the created sky or firmament (atmospheric and celestial heavens)",
      "basis": [
        "Genesis 1:1, 6-8",
        "Psalm 19:1",
        "Matthew 24:29"
      ],
      "prominence": "common"
    },
    {
      "meaning": "the intermediate abode of the righteous after death prior to resurrection and new creation",
      "basis": [
        "Luke 23:43",
        "2 Corinthians 5:8",
        "Revelation 6:9-11",
        "Philippians 1:23"
      ],
      "prominence": "common"
    },
    {
      "meaning": "a present spiritual state or reign of God rather than (or more than) a future location",
      "basis": [
        "Luke 17:20-21",
        "Matthew 5:3, 10",
        "select modern and mystical theological readings"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "synonym or near-synonym for the kingdom of God as present-and-future divine rule",
      "basis": [
        "Matthew's repeated 'kingdom of heaven'",
        "parallel kingdom sayings in Mark/Luke"
      ],
      "prominence": "common"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Broad Christian consensus treats heaven primarily as God's dwelling and the believers' eschatological home; variations concern intermediate vs. final state, place vs. state language, and literal vs. metaphorical emphasis, but these do not displace the core symbolic sense in mainstream teaching and biblical interpretation."
}
